\label{prop:d4-final-common-centralizer}
Over every commutative ring $R$ with $2\in R^\times$,
\begin{equation}
 \operatorname{Cent}_{M_8(R)}(\mathcal S)=RP_+\oplus RP_-=RI_8+RQ_0,
 \qquad \det(uP_++vP_-)=u^7v.
 \label{eq:d4-final-centralizer}
\end{equation}

\label{thm:relative}
Let $(S,\rho_S)$ be arbitrary, let $(A,\rho_A)$ be local, and suppose
$\Psi:E_S\to E_A$ satisfies Definition~\ref{def:prepared}.
There are unique $g\in G_A$ and a unital ring homomorphism
$\eta:S\to A$ satisfying $\eta T_S=T_A\eta$,
$\eta(S_0)\subseteq A_0$, and
\begin{equation}
 \Psi(y_{\gamma,S}(t))
 =g\,y_{\gamma,A}(\eta(t))g^{-1}
 \qquad(\gamma\in G_2,\ t\in S_\gamma).
 \label{eq:relative-root-rule}
\end{equation}
For any preparation $h$, one has $\bar g=\bar h$.
Under \eqref{eq:typed-rs}, also $\overline{\eta(t)}=\nu(t)$
for every $t\in S$.
No injectivity or surjectivity of $\Psi$ is required.

\label{prop:congruence}\label{prop:cover-cell}
For every chamber $C$,
$D_R=\widetilde U_C(J)L_R^1\widetilde U_{-C}(J)$.

\label{lem:trace-polynomials}
If $2,3\in A^\times$, a trace-preserving map $\eta:S\to A$ preserves
$\#$, $N$, and $\times$, and sends $S^{\rho_S}$ into $A^{\rho_A}$.

\label{lem:unit-generation}
If $H$ contains a short or long root element with a unit parameter,
then $H=E_R$.

\label{lem:extraction}
Let $H\trianglelefteq E_R$.
\begin{enumerate}
\item If a product of factors from distinct positive root subgroups
belongs to $H$, then every factor belongs to $H$, regardless of order.
\item If $y_a(t)Xhu^-\in H$, where $t\in R_0$, $X\in U_0$,
$h\in T_Q(R)^\delta$, and $u^-\in U^-$, then $y_a(t)\in H$.
\end{enumerate}

\label{lem:field-factor}
There are $\bar g\in G_Q(k)$, $\nu\in\operatorname{Aut}(k)$, and
$\epsilon\in\{1,-1\}$ such that
\begin{equation}
 \nu\bar\rho=\bar\rho^\epsilon\nu,\qquad
 \bar\alpha=\operatorname{Int}(\bar g)\circ\Phi_\nu^\epsilon.
 \label{eq:local-residual-factor}
\end{equation}
The element $\bar g$ lifts to $G_Q(R)$. Thus $\alpha$ satisfies
\eqref{eq:typed-rs} with coefficient map $\nu\circ\kappa_R$,
quotient $k$, and group image $H=E_k$.

\label{lem:perfect}
One has $E_Q=[E_Q,E_Q]=[G_Q,G_Q]$.
Thus $E_Q$ is characteristic in $G_Q$, and $E_P=G_P$ is perfect.
